export type CategoryId =
  | "information-manipulation"
  | "choice-manipulation"
  | "agency-manipulation"
  | "engagement-exploitation"
  | "social-exploitation"
  | "compound-adversarial-architecture";

export interface Category {
  id: CategoryId;
  name: string;
  description: string;
}

export const CATEGORIES: Category[] = [
  { id: "information-manipulation", name: "Information Manipulation", description: "Patterns that hide, distort, or degrade the information needed for an informed decision." },
  { id: "choice-manipulation", name: "Choice Manipulation", description: "Patterns that rig the decision architecture while leaving the nominal options visible." },
  { id: "agency-manipulation", name: "Agency Manipulation", description: "Patterns that obstruct, automate, or asymmetrically burden the user's actions." },
  { id: "engagement-exploitation", name: "Engagement Exploitation", description: "Patterns that exploit time, attention, and self-regulation to drive continued engagement." },
  { id: "social-exploitation", name: "Social Exploitation", description: "Patterns that weaponize social relationships, contacts, and trust." },
  { id: "compound-adversarial-architecture", name: "Compound Adversarial Architecture", description: "A compound dark stack that combines multiple adversarial patterns." },
];

/** A single formal condition for the dark pattern, rendered with KaTeX. */
export interface Condition {
  /** Short title, e.g. "Autonomous Media Execution". */
  title: string;
  /** Plain-English description of the condition. */
  description: string;
  /** KaTeX-compatible LaTeX source for the predicate. */
  formula?: string;
  /** Optional additional LaTeX for the "given" clause. */
  given?: string;
  /** Optional explanatory note rendered beneath the formula. */
  note?: string;
}

export interface ConditionDemo {
  /** 0-based index into the conditions array this demo illustrates. */
  conditionIndex: number;
  /** Slug key into the demo registry (pattern-demo.tsx). */
  demoSlug: string;
}

export interface Pattern {
  slug: string;
  name: string;
  category: CategoryId;
  /** One-paragraph description shown on the card and at the top of the subpage. */
  summary: string;
  /** Lucide icon name — keyed here to a stable icon import. */
  iconName: IconName;
  /** Whether the subpage ships a full interactive demo. */
  built: boolean;
  /** Optional formal conditions shown on the subpage. */
  conditions?: Condition[];
  /**
   * Per-condition demos. When present the page renders one demo per entry
   * instead of the single legacy demo looked up by `slug`. Each entry maps
   * a condition index to a demo component key in the registry.
   */
  conditionDemos?: ConditionDemo[];
  /** Related patterns the reader should look at next. */
  related?: string[];
  /** Reference number in the source taxonomy (Mathur et al., Brignull, Gray et al.). */
  references?: string[];
}

